@extends('layouts.app') @section('content')<div class="container my-3"><article class="paper-card"><div class="section-title">Payment Details</div><div class="paper-body"><p><b>Applicant:</b> {{ $data['name'] }}<br><b>Amount:</b> ₹{{ number_format($data['amount'],2) }}</p><button id="pay-button" class="btn btn-isar">Pay securely with Razorpay</button><p id="pay-message" class="mt-3 text-danger"></p></div></article></div>@endsection @push('scripts')<script src="https://checkout.razorpay.com/v1/checkout.js"></script><script>document.getElementById('pay-button').onclick=async()=>{let r=await fetch('{{ route('pay.order') }}',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':'{{ csrf_token() }}'},body:JSON.stringify({amount:{{ $data['amount'] }},reference:'{{ $data['reference'] ?? '' }}'})});if(!r.ok){document.getElementById('pay-message').textContent='Online payment is currently unavailable. Please contact the editorial office.';return}let o=await r.json();new Razorpay({key:o.key,amount:o.amount,currency:o.currency,name:'ISAR Publisher',order_id:o.id,handler:p=>{let f=document.createElement('form');f.method='POST';f.action='{{ route('pay') }}';f.innerHTML='<input name="_token" value="{{ csrf_token() }}">'+Object.entries(p).map(([k,v])=>'<input name="'+k+'" value="'+v+'">').join('');document.body.append(f);f.submit()}}).open()}</script>@endpush
